/* efpga.h - bare-metal driver for efpga_axil (A72 standalone or your RV32IM SoC)
 *
 *   #include "efpga.h"
 *   #include "counter14.h"            // generated by scripts/compile_user_design.sh
 *   efpga_configure(EFPGA_BASE, bs_counter14, bs_counter14_len);
 *   efpga_pulse(EFPGA_BASE, 0x3, 1);  // rst + en, exactly 1 clock
 *   efpga_pulse(EFPGA_BASE, 0x2, 1000);
 *   uint32_t v = (efpga_rd(EFPGA_BASE, EFPGA_IO_OUT) >> 2) & 0x3fff;   // 0x03e8
 */
#ifndef EFPGA_H
#define EFPGA_H
#include <stdint.h>

#define EFPGA_ID        0x00u
#define EFPGA_CTRL      0x04u
#define EFPGA_STATUS    0x08u
#define EFPGA_CFG_DATA  0x0Cu
#define EFPGA_CFG_COUNT 0x10u
#define EFPGA_IO_IN     0x14u
#define EFPGA_IO_OUT    0x18u
#define EFPGA_IO_OE     0x1Cu
#define EFPGA_SCRATCH   0x20u
#define EFPGA_CYCLES    0x24u
#define EFPGA_IO_PULSE  0x28u

#define EFPGA_ID_VALUE          0xEF0A0001u
#define EFPGA_CTRL_CFG_MODE     (1u << 0)
#define EFPGA_CTRL_CFG_RESET    (1u << 1)
#define EFPGA_CTRL_IN_SEL       (1u << 2)
#define EFPGA_STATUS_CFG_BUSY   (1u << 0)
#define EFPGA_STATUS_PULSE_BUSY (1u << 3)

static inline uint32_t efpga_rd(uintptr_t base, uint32_t off)
{
    return *(volatile uint32_t *)(base + off);
}

static inline void efpga_wr(uintptr_t base, uint32_t off, uint32_t v)
{
    *(volatile uint32_t *)(base + off) = v;
}

/* returns 0 on success, -1 if the ID is wrong, -2 if the word count mismatches */
static inline int efpga_configure(uintptr_t base, const uint32_t *bs, uint32_t len)
{
    uint32_t i;
    if (efpga_rd(base, EFPGA_ID) != EFPGA_ID_VALUE)
        return -1;
    efpga_wr(base, EFPGA_CTRL, EFPGA_CTRL_CFG_MODE | EFPGA_CTRL_CFG_RESET);
    for (i = 0; i < len; i++)          /* write response is held for 5 fabric clocks */
        efpga_wr(base, EFPGA_CFG_DATA, bs[i]);
    if (efpga_rd(base, EFPGA_CFG_COUNT) != len)
        return -2;
    efpga_wr(base, EFPGA_IO_IN, 0);
    efpga_wr(base, EFPGA_CTRL, 0);
    return 0;
}

/* drive IO_IN | mask into the fabric for exactly `count` fabric clocks */
static inline void efpga_pulse(uintptr_t base, uint16_t mask, uint16_t count)
{
    efpga_wr(base, EFPGA_IO_PULSE, ((uint32_t)count << 16) | mask);
    while (efpga_rd(base, EFPGA_STATUS) & EFPGA_STATUS_PULSE_BUSY)
        ;
}

#endif /* EFPGA_H */
